fn main() {
    let double = |x| x * 2;
    println!("{}", double(5));

    let offset = 100;
    let add_offset = |x: i32| x + offset;
    println!("{}", add_offset(5));

    let mut calls = 0;
    let mut tally = |x: i32| {
        calls += 1;
        x + calls
    };
    println!("{}", tally(10));
    println!("{}", tally(10));
}

fn main() {
    let mut v = vec![1, 2, 3, 4];

    let mut total = 0;
    for n in v.iter() {
        total += n;
    }
    println!("borrowed total {total}");
    println!("v is still here: {v:?}");

    for n in v.iter_mut() {
        *n *= 10;
    }
    println!("after iter_mut: {v:?}");

    let mut owned = 0;
    for n in v.into_iter() {
        owned += n;
    }
    println!("owned total {owned}");
}

