fn main() {
    let names = vec![
        String::from("ada"),
        String::from("alan"),
        String::from("grace"),
        String::from("bob"),
    ];

    let long_shouty: Vec<String> = names
        .iter()
        .filter(|n| n.len() > 3)
        .map(|n| n.to_uppercase())
        .collect();

    println!("{long_shouty:?}");
    println!("kept {} of {}", long_shouty.len(), names.len());
}

fn main() {
    let scores = vec![8.5, 9.0, 7.25];

    for (i, score) in scores.iter().enumerate() {
        println!("{i}: {score}");
    }

    let names = vec![String::from("ada"), String::from("bob")];
    for (name, score) in names.iter().zip(scores.iter()) {
        println!("{name} scored {score}");
    }

    let first_two: f64 = scores.iter().take(2).sum();
    println!("first two total {first_two}");
}

fn main() {
    let scores = vec![8.5, 9.0, 7.25];

    let product: f64 = scores.iter().fold(2.0, |acc, s| acc * s);
    println!("product {product}");
    println!("count {}", scores.iter().count());

    let mut names = vec![
        String::from("grace"),
        String::from("ada"),
        String::from("bob"),
    ];
    names.sort_by_key(|n| n.len());
    println!("{names:?}");
}

